bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *port_start = NULL;
    char *address = NULL;
    size_t address_len = 0;
    size_t port_len = 0;

    if (!pool || !url) {
        return false;
    }

    // Check for IPv6 address in brackets
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }
        address_len = end - start;
        address = start;
        start = end + 1;
    }

    // Check for port
    if (start && *start == ':') {
        start++;
        port_start = start;
        port_len = strlen(start);
    }

    // Validate URL length
    if (address_len > SIZE_MAX || (port_start && port_len > SIZE_MAX)) {
        return false;
    }

    // Copy address to pool
    if (address_len > 0) {
        char *address_copy = (char *)malloc(address_len + 1);
        if (!address_copy) {
            return false;
        }
        strncpy(address_copy, address, address_len);
        address_copy[address_len] = '\0';
        pool->socket_address = address_copy;
    }

    // Set default port if none specified
    if (port_start) {
        char *port_copy = (char *)malloc(port_len + 1);
        if (!port_copy) {
            return false;
        }
        strncpy(port_copy, port_start, port_len);
        port_copy[port_len] = '\0';
        pool->port = port_copy;
    } else {
        pool->port = "80";
    }

    return true;
}
